function LadderCompetionSeasonRewardDialog:InitRewardData_()
    self.rewardDataList_ = {}

    ---@type LadderGradeVo[]
    local gradeVoList = CfUtils.GetWholeVo(AutoIds.IdSetting2561, 'LadderGradeVo')
    for _, gradeVo in ipairs(gradeVoList) do
        table.insert(self.rewardDataList_, {
            gradeVo    = gradeVo,
            gradeScore = checkInt(gradeVo.scoreBegin),
        })
    end

    table.sort(self.rewardDataList_, function(aData, bData)
        return aData.gradeScore > bData.gradeScore
    end)
end


function LadderCompetionSeasonRewardDialog:RefreshView_()
    self:RefreshRewardList_()
end


function LadderCompetionSeasonRewardDialog:RefreshRewardList_()
    GameUtils.ReloadData(self.RewardGridView, #self.rewardDataList_)
end


